// ---- This node ----
// websitePlan.md §15.4. LinkedIn takes a video in 4 MiB parts, one upload URL
// each (uploadInstructions). Each part is a ranged GET from S3 relayed
// straight into that part's PUT, so at most PART_CONCURRENCY parts are in
// memory and nothing lands in n8n's binary storage. Each GET and PUT is
// retried on its own.
const PART_CONCURRENCY = 1;

const req = $('Parse Request').first().json;
const parts = $input.first().json.value.uploadInstructions;
const sourceUrl = req.media_urls[0];
const started = Date.now();

const uploadedPartIds = new Array(parts.length);
async function relayPart(index) {
  const part = parts[index];
  const chunk = await withRetry(() => readRange(sourceUrl, part.firstByte, part.lastByte));
  const res = await withRetry(async () => {
    const put = await send('PUT', part.uploadUrl, {
      Authorization: 'Bearer ' + req.access_token,
      'Content-Type': chunk.contentType,
      'Content-Length': chunk.body.length,
    }, chunk.body);
    if (put.status < 200 || put.status >= 300) throw httpError(put);
    return put;
  });
  if (!res.headers.etag) throw new Error('LinkedIn returned no ETag for part ' + (index + 1) + ' of ' + parts.length);
  uploadedPartIds[index] = res.headers.etag;
}

let next = 0;
async function worker() {
  while (next < parts.length) await relayPart(next++);
}
await Promise.all(Array.from({ length: Math.min(PART_CONCURRENCY, parts.length) }, worker));

// finalizeUpload wants the ETags in uploadInstructions order.
return [{
  json: {
    uploadedPartIds,
    parts: parts.length,
    bytes: parts.length ? parts[parts.length - 1].lastByte + 1 : 0,
    retries,
    seconds: Math.round((Date.now() - started) / 1000),
  },
}];
